Respond with a JSON object in the following order of fields: `blueprint` (must be formatted as a valid Python BlueprintDraft).

{
  "blueprint": {
    "objectives": [
      {
        "requirement_id": "http-api:explain-http-retry",
        "skill_id": "http-api",
        "criteria": [
          {
            "description": "Giải thích khái niệm tính idempotent trong HTTP và tại sao nó quan trọng khi retry.",
            "expected_evidence": "Ứng viên định nghĩa được rằng một yêu cầu là idempotent nếu thực hiện nhiều lần cho cùng kết quả như thực hiện một lần. Ví dụ: GET, PUT (với cùng payload), DELETE là idempotent; POST thường không.",
            "below_target": "Không thể định nghĩa idempotent hoặc nhầm lẫn với các thuộc tính khác của HTTP (như stateless).",
            "at_target": "Định nghĩa chính xác tính idempotent và nêu ví dụ cơ bản về phương thức HTTP liên quan.",
            "above_target": "Phân tích sâu hơn về cách áp dụng idempotent vào thiết kế API RESTful để đảm bảo an toàn khi retry."
          },
          {
            "description": "Áp dụng kiến thức về idempotent để giải quyết tình huống retry sau timeout khi cập nhật đơn hàng.",
            "expected_evidence": "Đề xuất sử dụng phương thức PUT hoặc PATCH (nếu hỗ trợ partial update) thay vì POST cho việc cập nhật đơn hàng cụ thể, hoặc sử dụng client-side idempotency key. Giải thích lý do lựa chọn dựa trên việc tránh tạo ra nhiều đơn hàng trùng lặp.",
            "below_target": "Đề xuất retry bằng POST mà không có cơ chế kiểm tra trùng lặp hoặc idempotency key, dẫn đến rủi ro dữ liệu sai lệch.",
            "at_target": "Nhận diện rủi ro từ retry POST và đề xuất giải pháp kỹ thuật (PUT/PATCH/Idempotency Key) để đảm bảo chỉ một đơn hàng được tạo/cập nhật.",
            "above_target": "Thiết kế cơ chế idempotency key toàn diện, bao gồm lưu trữ trạng thái request đã xử lý và xử lý race condition."
          }
        ],
        "suitable_modes": [
          {
            "mode": "TECHNICAL_EXPLANATION",
            "criterion_indices": [0]
          },
          {
            "mode": "DESIGN",
            "criterion_indices": [1]
          }
        ],
        "target_depth": 3,
        "depth_basis": "Analysis & Problem Solving",
        "depth_evidence_spans": [
          "Bắt buộc: Giải thích tính idempotent của HTTP khi retry yêu cầu cập nhật đơn hàng sau timeout."
        ],
        "depth_rationale": "Yêu cầu đòi hỏi phải phân tích nguyên nhân (timeout) và giải quyết vấn đề (tránh trùng lặp đơn hàng) thông qua việc áp dụng nguyên tắc idempotent, vượt quá ứng dụng cơ bản (L2) nhưng chưa cần thiết kế hệ thống phức tạp (L4)."
      },
      {
        "requirement_id": "incident-collaboration:coordinate-mitigation",
        "skill_id": "incident-collaboration",
        "criteria": [
          {
            "description": "Xác định vai trò và trách nhiệm của QA, SRE và Dev trong việc giảm thiểu tác động sự cố đơn hàng.",
            "expected_evidence": "Liệt kê được các hành động cụ thể: QA kiểm tra regression, SRE giám sát hạ tầng và rollback, Dev sửa lỗi code. Mô tả cách phối hợp giữa các bên.",
            "below_target": "Không rõ vai trò của từng bên hoặc đề xuất hành động không phù hợp với chuyên môn (ví dụ: Dev tự rollback hạ tầng mà không cần SRE).",
            "at_target": "Mô tả đúng quy trình phối hợp cơ bản giữa QA, SRE và Dev để giảm thiểu tác động sự cố.",
            "above_target": "Đề xuất quy trình phối hợp tối ưu, bao gồm communication plan và escalation path rõ ràng."
          },
          {
            "description": "Thực hiện bàn giao theo dõi sự cố sau khi đã giảm thiểu tác động ban đầu.",
            "expected_evidence": "Tạo ticket/báo cáo chi tiết về sự cố, liệt kê các bước đã thực hiện, trạng thái hiện tại và các bước tiếp theo cần làm. Bàn giao rõ ràng cho đội ngũ liên quan (QA/SRE) để theo dõi dài hạn.",
            "below_target": "Bàn giao thiếu thông tin, không rõ ràng hoặc không có bằng chứng về việc chuyển giao trách nhiệm.",
            "at_target": "Hoàn thành bàn giao với đầy đủ thông tin cần thiết để đội ngũ khác có thể tiếp tục theo dõi và xử lý.",
            "above_target": "Tích hợp bàn giao vào hệ thống quản lý sự cố tự động và đề xuất các biện pháp phòng ngừa tương lai."
          }
        ],
        "suitable_modes": [
          {
            "mode": "BEHAVIORAL",
            "criterion_indices": [0, 1]
          }
        ],
        "target_depth": 3,
        "depth_basis": "Analysis & Problem Solving",
        "depth_evidence_spans": [
          "Bắt buộc: Phối hợp với QA và SRE để thống nhất giảm thiểu tác động và bàn giao theo dõi trong sự cố đơn hàng."
        ],
        "depth_rationale": "Yêu cầu đòi hỏi khả năng phân tích tình huống sự cố, phối hợp đa bên để giải quyết vấn đề tức thời và bàn giao hiệu quả, thuộc mức độ phân tích và giải quyết vấn đề."
      },
      {
        "requirement_id": "docker:write-dev-container",
        "skill_id": "docker",
        "criteria": [
          {
            "description": "Viết Dockerfile tối giản cho API nội bộ.",
            "expected_evidence": "Sử dụng multi-stage build hoặc image base nhẹ (như alpine). Chỉ include các dependencies cần thiết cho runtime. Không include dev tools, source code test, hay các file không cần thiết.",
            "below_target": "Dockerfile chứa toàn bộ source code, dev dependencies, hoặc sử dụng image base quá nặng (như ubuntu full) mà không tối ưu.",
            "at_target": "Dockerfile hoạt động được, tối giản kích thước image so với mặc định, và chỉ include các thành phần cần thiết cho runtime.",
            "above_target": "Áp dụng best practices nâng cao như non-root user, healthcheck, và multi-stage build để tách biệt build và runtime environments."
          },
          {
            "description": "Đảm bảo Dockerfile phù hợp cho môi trường phát triển.",
            "expected_evidence": "Cấu hình port mapping, volume mount cho code source (để hot reload), và environment variables cần thiết cho dev. Giải thích lý do cấu hình này hỗ trợ dev workflow.",
            "below_target": "Dockerfile chỉ chạy được trong production, không hỗ trợ dev workflow (ví dụ: không mount volume, không expose port dev).",
            "at_target": "Cấu hình Dockerfile hỗ trợ đầy đủ các nhu cầu cơ bản của developer (chạy local, debug, hot reload).",
            "above_target": "Tối ưu hóa trải nghiệm developer với tooling như docker-compose.dev.yml, caching layer hiệu quả."
          }
        ],
        "suitable_modes": [
          {
            "mode": "CODING",
            "criterion_indices": [0, 1]
          }
        ],
        "target_depth": 2,
        "depth_basis": "Application",
        "depth_evidence_spans": [
          "Điểm cộng: Viết Dockerfile tối giản cho API nội bộ dùng trong môi trường phát triển."
        ],
        "depth_rationale": "Yêu cầu là viết Dockerfile, một task ứng dụng trực tiếp kiến thức Docker vào một task cụ thể (dev container). Đây là mức độ ứng dụng (L2) vì không yêu cầu phân tích phức tạp hay thiết kế hệ thống lớn."
      }
    ]
  }
}

{
  "blueprint": {
    "objectives": [
      {
        "requirement_id": "postgresql:diagnose-order-query",
        "skill_id": "postgresql",
        "criteria": [
          {
            "description": "Xác định nguyên nhân gây chậm truy vấn lọc và sắp xếp đơn hàng trên bảng lớn.",
            "expected_evidence": "Ứng viên phân tích `EXPLAIN ANALYZE`, chỉ ra việc thiếu index hoặc sử dụng sequential scan, và giải thích tại sao sorting trên cột không có index gây tốn CPU/Memory.",
            "below_target": "Không thể đọc kết quả EXPLAIN hoặc đề xuất xóa toàn bộ dữ liệu để test.",
            "at_target": "Chỉ ra được cần tạo index bao gồm các cột WHERE và ORDER BY (composite index) hoặc đề xuất partitioning nếu dữ liệu quá lớn. Giải thích trade-off giữa write overhead và read speed.",
            "above_target": "Đề xuất chiến lược partitioning theo thời gian hoặc hash, hoặc tối ưu hóa shared_buffers/work_mem cho workload cụ thể này."
          },
          {
            "description": "Viết cú pháp SQL hợp lệ để tạo index hoặc sửa đổi truy vấn nhằm tối ưu hiệu năng.",
            "expected_evidence": "Cung cấp câu lệnh `CREATE INDEX` chính xác với cú pháp PostgreSQL, hoặc viết lại truy vấn sử dụng index phù hợp.",
            "below_target": "Sai cú pháp SQL cơ bản hoặc đề xuất index không liên quan đến điều kiện lọc/sắp xếp.",
            "at_target": "Tạo composite index đúng thứ tự cột (WHERE trước, ORDER BY sau) hoặc sử dụng partial index nếu điều kiện lọc đặc thù.",
            "above_target": "Sử dụng covering index (INCLUDE) để tránh lookup bảng, hoặc đề xuất BRIN index nếu dữ liệu có tính chất tuần tự mạnh."
          }
        ],
        "suitable_modes": [
          {
            "mode": "DEBUGGING"
          },
          {
            "mode": "DESIGN"
          }
        ],
        "target_depth": 3,
        "depth_basis": "ANALYSIS_PROBLEM_SOLVING",
        "depth_evidence_spans": [
          "Chẩn đoán và tối ưu truy vấn PostgreSQL lọc và sắp xếp danh sách đơn hàng trên bảng lớn."
        ],
        "depth_rationale": "Yêu cầu chẩn đoán (debugging) nguyên nhân chậm và đưa ra giải pháp tối ưu (design/analysis) cho một tình huống cụ thể (bảng lớn), vượt xa việc áp dụng công thức đơn thuần.",
        "estimated_seconds": 180
      },
      {
        "requirement_id": "python:deduplicate-events",
        "skill_id": "python",
        "criteria": [
          {
            "description": "Triển khai thuật toán loại bỏ phần tử trùng lặp trong danh sách sự kiện mà vẫn giữ nguyên thứ tự xuất hiện đầu tiên.",
            "expected_evidence": "Viết hàm Python nhận vào list/dict của các event objects, trả về list đã loại trùng. Sử dụng cấu trúc dữ liệu hỗ trợ tra cứu nhanh (set/dict) để đảm bảo độ phức tạp thời gian tốt.",
            "below_target": "Sử dụng cách tiếp cận O(N^2) so sánh từng cặp phần tử, hoặc dùng `list(set(...))` làm mất thứ tự.",
            "at_target": "Sử dụng `dict.fromkeys()` (Python 3.7+) hoặc vòng lặp kết hợp `seen` set để duy trì thứ tự và đạt O(N).",
            "above_target": "Xử lý trường hợp event là object phức tạp (cần định nghĩa key/hashable), hoặc tối ưu bộ nhớ khi xử lý stream dữ liệu khổng lồ bằng generator."
          },
          {
            "description": "Xử lý các trường hợp biên như sự kiện có trường khóa là None hoặc kiểu dữ liệu không hashable.",
            "expected_evidence": "Kiểm tra và xử lý ngoại lệ hoặc chuyển đổi khóa thành dạng hashable (ví dụ: tuple của các thuộc tính).",
            "below_target": "Code bị crash khi gặp giá trị None hoặc dict không hashable.",
            "at_target": "Lọc bỏ hoặc gán giá trị mặc định cho khóa null, hoặc chuyển đổi object thành tuple để lưu vào set.",
            "above_target": "Thiết kế cơ chế fallback hoặc logging chi tiết khi phát hiện dữ liệu không hợp lệ để debug dễ dàng hơn."
          }
        ],
        "suitable_modes": [
          {
            "mode": "CODING"
          }
        ],
        "target_depth": 2,
        "depth_basis": "APPLICATION",
        "depth_evidence_spans": [
          "Viết hàm Python loại trùng sự kiện đơn hàng theo mã sự kiện, giữ nguyên thứ tự xuất hiện đầu tiên."
        ],
        "depth_rationale": "Đây là một tác vụ lập trình cụ thể, bounded task yêu cầu áp dụng kiến thức cơ bản về cấu trúc dữ liệu và ngôn ngữ Python để giải quyết vấn đề logic rõ ràng.",
        "estimated_seconds": 120
      },
      {
        "requirement_id": "rabbitmq:design-payment-consumer",
        "skill_id": "rabbitmq",
        "criteria": [
          {
            "description": "Thiết kế cơ chế xử lý tin nhắn thanh toán để đảm bảo không ghi nhận thanh toán hai lần (idempotency) khi có message redelivery.",
            "expected_evidence": "Mô tả cách consumer kiểm tra trạng thái giao dịch trước khi xử lý (ví dụ: check DB status 'paid' hoặc dùng distributed lock/cache). Đề xuất pattern xử lý lỗi và retry.",
            "below_target": "Không đề cập đến cơ chế idempotency, giả định mỗi tin nhắn chỉ đến một lần, hoặc xử lý đồng bộ blocking gây nghẽn.",
            "at_target": "Thực hiện kiểm tra trạng thái giao dịch trong DB trước khi update, sử dụng transaction để đảm bảo atomicity giữa việc đọc trạng thái và cập nhật.",
            "above_target": "Sử dụng external idempotency store (Redis) với TTL, hoặc thiết kế consumer stateless kết hợp với correlation ID để scale horizontal dễ dàng."
          },
          {
            "description": "Xác định cấu hình RabbitMQ phù hợp (acknowledgment, prefetch, queue type) để cân bằng giữa độ tin cậy và hiệu năng.",
            "expected_evidence": "Khuyến nghị `manual ack`, `prefetch_count=1` (hoặc giá trị phù hợp workload), và queue durable/persistent nếu cần đảm bảo không mất tin nhắn.",
            "below_target": "Sử dụng auto-ack mặc định dẫn đến mất tin nhắn khi consumer crash, hoặc cấu hình prefetch quá cao gây tràn memory.",
            "at_target": "Cấu hình manual ack, prefetch hợp lý, và declare queue với durable=true để chịu đựng restart broker.",
            "above_target": "Đề xuất sử dụng Quorum Queues cho high availability cluster, hoặc implement dead-letter exchange (DLX) để xử lý messages lỗi vĩnh viễn."
          }
        ],
        "suitable_modes": [
          {
            "mode": "DESIGN"
          },
          {
            "mode": "TECHNICAL_EXPLANATION"
          }
        ],
        "target_depth": 4,
        "depth_basis": "DESIGN_TRADE_OFFS",
        "depth_evidence_spans": [
          "Thiết kế consumer RabbitMQ cho sự kiện thanh toán để việc giao lại thông điệp không ghi nhận thanh toán hai lần."
        ],
        "depth_rationale": "Yêu cầu thiết kế một hệ thống phân tán với các ràng buộc nghiêm ngặt về tính nhất quán (không double charge) và độ tin cậy, đòi hỏi đánh đổi giữa consistency, availability và latency.",
        "estimated_seconds": 180
      }
    ]
  }
}
